  const ctx = use(TimelineRowCtx);
  const pastedText = file.source?._tag === "pasted-text";
  const label = userMessageFileLabel(file);
  const extension = /\.([a-z0-9]{1,8})$/i.exec(file.name)?.[1]?.toUpperCase() ?? "File";
  const identity = (
