      unsupported && !savedEnvironment
        ? `T3 Connect · ${notAdded} · Client not supported`
        : offlineReason !== null
          ? offlineReason
          : savedConnection
            ? savedConnection.statusText
            : availability === "online"
              ? `T3 Connect · ${notAdded} · Relay online`
              : availability === "offline"
                ? `T3 Connect · ${notAdded} · Relay offline`
