                    checked={!feedbackUnavailable && settings.snapShotAnimations}
                    disabled={!captureAvailable || Boolean(feedbackUnavailable)}
                    aria-label="Animate snapshots"
                    onCheckedChange={(checked) => void save({ snapShotAnimations: checked })}
                  />
                }
