                  label: environment.label,
                  previous,
                  patch: forDestination(
                    previous,
                    previous.worktreeCleanup != null &&
                      serverPatch.storageCleanup &&
                      Object.keys(serverPatch.storageCleanup).some((key) =>
                        key.startsWith("worktree"),
                      )
                      ? {
                          ...serverPatch,
                          worktreeCleanup: {
                            mode: "custom",
                            rules: {
