      }
      return new ConnectionBlockedError({
        reason: "configuration",
        detail: `${descriptor.label} runs Blackcrab ${descriptor.serverVersion}, but this desktop is ${APP_VERSION}, and that server could not accept its pairing. Restart the T3 server on ${descriptor.label} so it runs ${APP_VERSION}, then retry.`,
